-- APT/USD daily close (Coinbase Exchange APT-USD 1d candles, UTC day) for pricing UFC Strike Aptos sales,
-- shaped like sol_usd_daily. Backfill 2025-08-01..2026-11-15 read 2026-11-15 ~4:40 PM PT; the ufc-aptos ingest script upserts new days.
-- Plus the ingest cursor table for the ufc-aptos-sales lane (one row).
-- Revert: DROP TABLE public.apt_usd_daily; DROP TABLE public.ufc_aptos_ingest_state;
CREATE TABLE public.apt_usd_daily (
  day date PRIMARY KEY,
  usd numeric NOT NULL CHECK (usd > 0),
  source text NOT NULL,
  captured_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.apt_usd_daily ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.apt_usd_daily FROM anon, authenticated;
COMMENT ON TABLE public.apt_usd_daily IS 'APT/USD daily close, UTC day (Coinbase Exchange APT-USD granularity 86400). Prices UFC Strike Aptos sales (sales.currency=APT).';

